#!/usr/bin/env python3
"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration to
/app/output.txt following the rules in the task description.
"""

import re
import sys

METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
PERMISSIONS = {"ALLOW", "DENY"}
ROLE_RE = re.compile(r"^[A-Za-z0-9_-]+$")
# {name} where name is alphanumeric / underscore / hyphen
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def norm_path(path):
    """Normalize path variables to {var} for matching purposes."""
    return VAR_RE.sub("{var}", path)


def seg_count(path):
    """Number of non-empty segments when split on '/'."""
    return len([s for s in path.split("/") if s != ""])


def parse_input(text):
    """Split input into the three sections separated by empty lines."""
    lines = text.split("\n")
    # Drop any trailing empty line(s) produced by a final newline
    while lines and lines[-1].strip() == "":
        lines.pop()
    sections = []
    cur = []
    for line in lines:
        if line.strip() == "":
            sections.append(cur)
            cur = []
        else:
            cur.append(line)
    sections.append(cur)
    if len(sections) < 2:
        # Only one section present; treat as ENDPOINTS only
        while len(sections) < 3:
            sections.append([])
    elif len(sections) == 2:
        sections.append([])
    return sections[0], sections[1], sections[2]


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on first malformed line."""
    endpoints = []
    for line in lines:
        fields = line.split()
        if len(fields) != 4:
            break  # hard cutoff
        path, method, role, perm = fields
        if path.strip() == "":
            break
        method = method.upper()
        if method not in METHODS:
            break
        perm = perm.upper()
        if perm not in PERMISSIONS:
            break
        if role.strip() == "" or not ROLE_RE.match(role):
            break
        endpoints.append({"path": path, "method": method, "role": role,
                          "perm": perm})
    return endpoints


def parse_base_exclude(lines):
    base = None
    excluded = set()
    for line in lines:
        fields = line.split()
        if not fields:
            continue
        if fields[0] == "base" and len(fields) >= 2:
            base = fields[1]
        elif fields[0] == "exclude":
            for r in fields[1:]:
                excluded.add(r)
    return base, excluded


def parse_plan(lines):
    plan = []
    for line in lines:
        fields = line.split()
        if len(fields) != 2:
            break  # hard cutoff
        path, method = fields
        if path.strip() == "":
            break
        method = method.upper()
        if method not in METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open("/app/input.txt", "r") as f:
        text = f.read()

    ep_lines, be_lines, plan_lines = parse_input(text)
    endpoints = parse_endpoints(ep_lines)
    base, excluded = parse_base_exclude(be_lines)
    plan = parse_plan(plan_lines)

    # ---- Eligibility (base prefix + exclude) ----
    def base_ok(path):
        return base is None or path.startswith(base)

    def eligible(ep):
        return base_ok(ep["path"]) and ep["role"] not in excluded

    eligible_eps = [e for e in endpoints if eligible(e)]

    # Group endpoints by normalized path (input order preserved)
    norm_paths = []
    by_norm = {}
    for e in endpoints:
        np = norm_path(e["path"])
        if np not in by_norm:
            by_norm[np] = []
            norm_paths.append(np)
        by_norm[np].append(e)

    eligible_norm_paths = set(np for np in norm_paths
                              if any(eligible(e) for e in by_norm[np]))

    # ---- Determine which normalized paths are needed ----
    plan_norms = [norm_path(p) for p, _ in plan]
    plan_set = set(plan_norms)

    needed = set()
    if not plan:
        needed = set(eligible_norm_paths)
    else:
        for p in plan_set:
            if p not in by_norm:
                continue  # endpoint in PLAN not in ENDPOINTS -> ignored
            needed.add(p)
            # Parent paths: normalized prefix, not the same path, and the
            # parent path has at least one eligible endpoint
            for q in norm_paths:
                if q == p:
                    continue
                if p.startswith(q) and q in eligible_norm_paths:
                    needed.add(q)

    # ---- Build output entries ----
    # Track first original path per normalized path (input order)
    first_orig = {}
    for e in endpoints:
        np = norm_path(e["path"])
        if np not in first_orig:
            first_orig[np] = e["path"]

    # Special-case set: parent paths that have endpoints ONLY for excluded
    # roles but are needed for inheritance -> include them
    special_paths = set()
    if plan:
        for p in plan_set:
            if p not in by_norm:
                continue
            for q in norm_paths:
                if q == p or not p.startswith(q):
                    continue
                eps = by_norm[q]
                if not any(eligible(e) for e in eps):
                    special_paths.add(q)

    entries = []
    for np in norm_paths:
        if np in plan_set:
            include = True
        elif np in needed:
            include = True
        elif np in special_paths:
            include = True
        else:
            include = False
        if not include:
            continue
        for e in by_norm[np]:
            if eligible(e):
                entries.append((np, e))
            elif np in special_paths:
                entries.append((np, e))

    # ---- Dedup: one endpoint per (normalized path, method, role),
    # first encountered wins (input order) ----
    seen = set()
    final = []
    for np, e in entries:
        key = (np, e["method"], e["role"])
        if key in seen:
            continue
        seen.add(key)
        final.append((np, e))

    # ---- Ordering:
    # 1. segment count descending (more specific first)
    # 2. method alphabetical
    # 3. role lexicographic (case-sensitive)
    # 4. permission (ALLOW before DENY)
    perm_rank = {"ALLOW": 0, "DENY": 1}
    final.sort(key=lambda t: (-seg_count(t[1]["path"]), t[1]["method"],
                              t[1]["role"], perm_rank[t[1]["perm"]]))

    # ---- Output ----
    out_lines = []
    for np, e in final:
        out_lines.append("%s %s %s %s" % (first_orig[np], e["method"],
                                          e["role"], e["perm"]))
    out = ("\n".join(out_lines) + "\n") if out_lines else "\n"
    with open("/app/output.txt", "w") as f:
        f.write(out)


if __name__ == "__main__":
    main()
